<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
function sd_social_activity_query( $filter = 'public', $page = 1, $per_page = 10 ) { if ( ! function_exists( 'bp_activity_get' ) ) { return array(); } $args = array( 'per_page' => min( 20, max( 1, absint( $per_page ) ) ), 'page' => max( 1, absint( $page ) ), 'display_comments' => false, 'show_hidden' => false ); if ( 'mine' === $filter && is_user_logged_in() ) { $args['user_id'] = get_current_user_id(); } elseif ( 'friends' === $filter && function_exists( 'bp_is_active' ) && bp_is_active( 'friends' ) ) { $args['scope'] = 'friends'; } elseif ( 'mentions' === $filter && is_user_logged_in() ) { $args['scope'] = 'mentions'; } elseif ( 0 === strpos( $filter, 'group-' ) && function_exists( 'bp_is_active' ) && bp_is_active( 'groups' ) ) { $args['object'] = 'groups'; $args['primary_id'] = absint( substr( $filter, 6 ) ); } else { $args['scope'] = 'public'; } return bp_activity_get( $args ); }
function sd_social_activity_available() { return function_exists( 'bp_activity_get' ); }
function sd_social_activity_favorite_state( $activity_id ) { return is_user_logged_in() && function_exists( 'bp_activity_is_favorite' ) ? bp_activity_is_favorite( absint( $activity_id ) ) : false; }
function sd_social_activity_author( $activity ) { return function_exists( 'bp_core_get_user_displayname' ) ? bp_core_get_user_displayname( $activity->user_id ) : __( 'Member', 'social-discovery' ); }
function sd_social_activity_url( $activity ) { return function_exists( 'bp_activity_get_permalink' ) ? bp_activity_get_permalink( $activity ) : home_url( '/' ); }
